INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Teamarbeit
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist Teamarbeit in der IT immer abhängig von direkter face-to-face Kommunikation?', 2, '[{"text": "Nein", "correct": true, "because": "Digitale Tools ermöglichen remote Zusammenarbeit"}, {"text": "Ja", "correct": false, "because": "Teamarbeit ist auch virtuell möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann effektive Teamarbeit ohne klare Rollenverteilung gelingen?', 2, '[{"text": "Ja", "correct": true, "because": "Möglich, aber oft ineffizient"}, {"text": "Nein", "correct": false, "because": "Rollenverteilung ist hilfreich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Teammitglieder dieselben technischen Fähigkeiten besitzen, um erfolgreich zusammenzuarbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Vielfalt an Fähigkeiten stärkt Teams"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Kompetenzen sind oft nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Missverständnisse in der Teamkommunikation die Effizienz beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Unklarheiten führen zu Verzögerungen"}, {"text": "Nein", "correct": false, "because": "Kommunikation ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Teamarbeit ohne regelmäßigen Austausch langfristig produktiv?', 2, '[{"text": "Nein", "correct": true, "because": "Austausch fördert Koordination"}, {"text": "Ja", "correct": false, "because": "Fehlender Austausch mindert Effektivität"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird häufig für die Kommunikation in IT-Teams verwendet?', 3, '[{"text": "Slack", "correct": true, "because": "Beliebt für Team-Kollaboration"}, {"text": "Photoshop", "correct": false, "because": "Für Grafik, nicht Kommunikation"}, {"text": "Excel", "correct": false, "because": "Für Daten, nicht Austausch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für erfolgreiche Teamarbeit am wichtigsten?', 2, '[{"text": "Klar definierte Ziele", "correct": true, "because": "Gibt Richtung vor"}, {"text": "Einheitliche Kleidung", "correct": false, "because": "Irrelevant"}, {"text": "Maximale Teamgröße", "correct": false, "because": "Weniger entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Teamarbeit in der Kommunikation?', 2, '[{"text": "Effiziente Problemlösung", "correct": true, "because": "Zusammenarbeit optimiert Ergebnisse"}, {"text": "Reduktion der Arbeitszeit", "correct": false, "because": "Nebenaspekt"}, {"text": "Vermeidung von Meetings", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch mangelnde Teamarbeit entstehen?', 3, '[{"text": "Doppelte Arbeit", "correct": true, "because": "Fehlende Koordination führt zu Redundanz"}, {"text": "Schnellere Projektabschlüsse", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Aufgabenverteilung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode fördert die Teamarbeit in agilen Projekten?', 2, '[{"text": "Daily Stand-ups", "correct": true, "because": "Kurze, regelmäßige Absprachen"}, {"text": "Jährliche Reviews", "correct": false, "because": "Zu selten"}, {"text": "Einzelarbeit", "correct": false, "because": "Widerspricht Teamarbeit"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren tragen zu erfolgreicher Teamarbeit bei?', 4, '[{"text": "Klare Kommunikation", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Gemeinsame Ziele", "correct": true, "because": "Fokussiert Team"}, {"text": "Vertrauen", "correct": true, "because": "Stärkt Zusammenarbeit"}, {"text": "Einheitliche Haarfarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen die Kommunikation in der Teamarbeit?', 3, '[{"text": "Microsoft Teams", "correct": true, "because": "Plattform für Austausch"}, {"text": "Jira", "correct": true, "because": "Projektmanagement und Kommunikation"}, {"text": "Trello", "correct": true, "because": "Aufgabenverfolgung"}, {"text": "Calculator", "correct": false, "because": "Nicht für Kommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Teamarbeit beeinträchtigen?', 4, '[{"text": "Unklare Rollen", "correct": true, "because": "Führt zu Konfusion"}, {"text": "Mangelnde Kommunikation", "correct": true, "because": "Verzögert Prozesse"}, {"text": "Fehlende Koordination", "correct": true, "because": "Mindert Effizienz"}, {"text": "Schnelle Entscheidungen", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Teamarbeit in der IT?', 3, '[{"text": "Schnellere Problemlösung", "correct": true, "because": "Mehr Perspektiven"}, {"text": "Bessere Qualität", "correct": true, "because": "Kombinierte Expertise"}, {"text": "Effizientere Ressourcennutzung", "correct": true, "because": "Aufgabenverteilung"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördern die Teamarbeit?', 3, '[{"text": "Offenheit", "correct": true, "because": "Fördert Austausch"}, {"text": "Flexibilität", "correct": true, "because": "Passt an Veränderungen"}, {"text": "Verantwortungsbewusstsein", "correct": true, "because": "Sichert Ergebnisse"}, {"text": "Technische Überlegenheit", "correct": false, "because": "Nicht entscheidend"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Teamarbeit erfordert regelmäßige Kommunikation. b) Alle Teammitglieder müssen denselben Standort teilen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation ja, Standort flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klare Ziele verbessern die Teamarbeit. b) Teamarbeit ist immer schneller als Einzelarbeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ziele ja, Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kommunikationstools können die Teamarbeit erleichtern. b) Teamarbeit erfordert keine Koordination.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tools ja, Koordination nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Unterschiedliche Fähigkeiten im Team fördern die Problemlösung. b) Teamarbeit ist nur bei großen Projekten sinnvoll.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fähigkeiten ja, Teamarbeit immer nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mangelnde Kommunikation kann die Teamarbeit behindern. b) Jedes Teammitglied muss alle Aufgaben kennen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation ja, Detailwissen nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

